import {useEffect,useMemo,useState} from 'react';
import {ArrowRight,RefreshCw,UserRoundPlus} from 'lucide-react';
import {createExternalClient} from '../../lib/fiteatsyConsultantsApi';
import {convertLead,createLead,listLeads,updateLeadStage} from '../../lib/practiceOperationsApi';
import PhoneNumberField,{PHONE_COUNTRIES,toE164} from './PhoneNumberField';

const STAGES=['NEW','CONTACTED','QUALIFIED','CONSULTATION_BOOKED','CONVERTED','NOT_INTERESTED','LOST'];
const NEXT={NEW:['CONTACTED','QUALIFIED','NOT_INTERESTED','LOST'],CONTACTED:['QUALIFIED','CONSULTATION_BOOKED','NOT_INTERESTED','LOST'],QUALIFIED:['CONTACTED','CONSULTATION_BOOKED','NOT_INTERESTED','LOST'],CONSULTATION_BOOKED:['QUALIFIED','CONVERTED','NOT_INTERESTED','LOST'],NOT_INTERESTED:['CONTACTED'],LOST:['CONTACTED'],CONVERTED:[]};
export function ExternalLeads({onClientCreated}){
  const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[open,setOpen]=useState(false),[stage,setStage]=useState('');
  const[form,setForm]=useState({first_name:'',last_name:'',email:'',country_iso2:'IN',national_number:'',source:'REFERRAL',notes:''});
  const load=async()=>{setState('loading');setError('');try{const result=await listLeads({stage});setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message||'Lead pipeline could not be loaded.');setState('error')}};
  useEffect(()=>{void load()},[stage]);
  const counts=useMemo(()=>Object.fromEntries(STAGES.map(value=>[value,items.filter(item=>item.stage===value).length])),[items]);
  const save=async event=>{event.preventDefault();setError('');try{const dial=PHONE_COUNTRIES.find(item=>item.iso===form.country_iso2)?.dial||'+91';await createLead({...form,phone:toE164(dial,form.national_number),country_iso2:undefined,national_number:undefined});setOpen(false);setForm({first_name:'',last_name:'',email:'',country_iso2:'IN',national_number:'',source:'REFERRAL',notes:''});await load()}catch(reason){setError(reason.message||'Lead could not be created.')}};
  const move=async(item,target)=>{setError('');try{if(target==='CONVERTED'){const client=await createExternalClient({firstName:item.first_name,lastName:item.last_name||'',email:item.email||'',mobile:item.phone||''});await convertLead(item.id,client.client.id);onClientCreated?.(client.client)}else await updateLeadStage(item.id,target);await load()}catch(reason){setError(reason.message||'Lead stage could not be changed.')}};
  return <section className="space-y-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Growth</p><h2 className="mt-1 text-3xl font-bold">Leads</h2><p className="mt-2 text-sm text-slate-600">A tenant-scoped prospect pipeline with governed Client Core conversion.</p></div><button onClick={()=>setOpen(true)} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white"><UserRoundPlus className="mr-2 inline" size={17}/>Add lead</button></header>
    <div className="flex gap-2 overflow-x-auto" aria-label="Lead stage filters"><button onClick={()=>setStage('')} aria-pressed={!stage} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-semibold ${!stage?'bg-blue-700 text-white':'border bg-white'}`}>All</button>{STAGES.map(value=><button key={value} onClick={()=>setStage(value)} aria-pressed={stage===value} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-semibold ${stage===value?'bg-blue-700 text-white':'border bg-white'}`}>{value.replaceAll('_',' ')} {!stage&&counts[value]?`· ${counts[value]}`:''}</button>)}</div>
    {error&&<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-800">{error}</p>}
    {state==='loading'?<div aria-label="Loading leads" className="h-40 animate-pulse rounded-3xl bg-white"/>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl border px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry leads</button>:items.length?<div className="grid gap-4 lg:grid-cols-2">{items.map(item=><article key={item.id} className="rounded-3xl border bg-white p-5"><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{item.first_name} {item.last_name}</p><p className="mt-1 text-sm text-slate-600">{item.email||item.phone} · {item.source.replaceAll('_',' ')}</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-800">{item.stage.replaceAll('_',' ')}</span></div>{item.duplicate_count>0&&<p className="mt-3 rounded-xl bg-amber-50 p-3 text-xs font-semibold text-amber-900">Possible duplicate contact detected in this practice.</p>}<div className="mt-4 flex flex-wrap gap-2">{NEXT[item.stage].map(target=><button key={target} onClick={()=>move(item,target)} className={`min-h-11 rounded-xl px-3 text-sm font-semibold ${target==='CONVERTED'?'bg-emerald-700 text-white':'border'}`}>{target==='CONVERTED'?'Convert to client':target.replaceAll('_',' ')}</button>)}</div></article>)}</div>:<div className="rounded-3xl border border-dashed bg-white p-8 text-center"><ArrowRight className="mx-auto text-slate-400"/><p className="mt-3 font-semibold">No leads in this view</p><p className="mt-1 text-sm text-slate-500">The pipeline request completed successfully.</p></div>}
    {open&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4" onClick={()=>setOpen(false)}><form onSubmit={save} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="lead-title" className="w-full max-w-xl rounded-3xl bg-white p-6"><h3 id="lead-title" className="text-xl font-bold">Add lead</h3><div className="mt-5 grid gap-4 sm:grid-cols-2">{[['First name','first_name','text'],['Last name','last_name','text'],['Email','email','email'],['Source','source','text']].map(([label,key,type])=><label key={key} className="text-sm font-semibold">{label}<input required={key==='first_name'||key==='source'} type={type} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label>)}<div className="sm:col-span-2"><PhoneNumberField label="Phone" countryIso2={form.country_iso2} onCountryChange={country_iso2=>setForm({...form,country_iso2})} nationalNumber={form.national_number} onNationalNumberChange={national_number=>setForm({...form,national_number})}/></div></div><label className="mt-4 block text-sm font-semibold">Notes<textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})} className="mt-2 min-h-24 w-full rounded-xl border p-3"/></label><div className="mt-6 flex gap-3"><button type="button" onClick={()=>setOpen(false)} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button disabled={!form.email&&!form.national_number} className="min-h-12 flex-1 rounded-xl bg-blue-700 font-semibold text-white disabled:opacity-40">Create lead</button></div></form></div>}
  </section>;
}
